-- Note-format customization — PHASE 1 seed re-sync (zero behavior change).
--
-- Phase 0 seeded the system-default template, but its section/preamble/rule
-- strings did NOT preserve Layer-4's exact line-wrapping. Phase 1 makes L4
-- BUILD its prompt from this row, so the row must be BYTE-FOR-BYTE the L4
-- prompt pieces or non-customizing doctors would get changed output. This
-- migration re-syncs the singleton system-default row to the byte-exact
-- content now in apps/transcribe-md/src/worker/note-templates/
-- system-default-template.ts (the golden test locks builder(row) === today's
-- prompt). DATA-only: no schema change; touches the one system-default row.
--
-- Idempotent: re-running sets the same values. The JSON below is kept in
-- lockstep with the TS source of truth (a drift test deep-equals the two).

UPDATE "note_templates"
SET
    /* @seed:sections */ "sections" = '[{"key":"subjective","label":"Subjective","order":1,"formatHint":"prose","styleInstructions":"**Chief Complaint:** …\n**HPI:** narrative paragraph incorporating onset, duration,\n  quality, severity, location, timing, context, modifying factors,\n  associated symptoms.\n**PMH:** bullet list or \"[not documented]\" if silent.\n**Medications:** bullet list with dose/route/frequency where stated.\n**Allergies:** bullet list with reactions where stated.\n**Family History:** brief list or \"[not documented]\".\n**Social History:** smoking / alcohol / drugs / occupation if\n  mentioned; omit unmentioned lines.\n**ROS:** by system when documented; else the single line\n  \"ROS not formally documented in this encounter.\"","defaultText":null,"defaultTextMode":"omit_unless_supported"},{"key":"objective","label":"Objective","order":2,"formatHint":"prose","styleInstructions":"Physical exam findings grouped by system. Include vitals if\nmentioned. Include test results mentioned. If no formal exam was\ndiscussed, write exactly: \"Formal exam not documented in this\nencounter.\"","defaultText":null,"defaultTextMode":"omit_unless_supported"},{"key":"assessment","label":"Assessment","order":3,"formatHint":"prose","styleInstructions":"Primary clinical consideration with supporting reasoning.\nDifferentials if the doctor discussed them. Severity/staging if\napplicable. Use [not documented] rather than inventing.","defaultText":null,"defaultTextMode":"omit_unless_supported"},{"key":"plan","label":"Plan","order":4,"formatHint":"numbered","styleInstructions":"Numbered list: diagnostics ordered, medications changed/started,\nfollow-up, referrals, patient education. Each item should be\nactionable.","defaultText":null,"defaultTextMode":"omit_unless_supported"}]'::jsonb,
    /* @seed:styleProfile */ "styleProfile" = '{"tense":null,"tone":"professional medical","abbreviations":null,"preamble":"You are a senior clinician writing a SOAP note from a clinical\nvisit. Use ONLY the entities provided and the transcript as\nevidence. Write in a professional medical tone.","globalRules":["- Do NOT invent clinical findings. If a claim lacks transcript\n  evidence, either omit it or explicitly mark it \"[not documented]\".","- When information came exclusively from the patient, prefix with\n  \"Per patient, …\" so the source is clear on downstream review.","- Never add test results, medication doses, or vital-sign numbers\n  that were not stated.","- Don''t add diagnostic qualifiers (acute, chronic, undiagnosed,\n  severe, mild, sudden, gradual) unless the transcript uses them\n  explicitly. \"Migraines\" stays \"migraines\" — not \"undiagnosed\n  migraines.\" Onset is \"sudden\" only if the patient said sudden.","- Don''t infer maternal/paternal side or a specific relative when\n  the transcript only mentions a relative type. \"My grandmother\"\n  stays \"grandmother\" — not \"maternal grandmother\" unless stated.","- When a dose, frequency, or strength is ambiguous in the\n  transcript, write what was actually said and append\n  ''[clarify with patient]'' rather than picking the most likely\n  value. Don''t silently resolve \"two tablets... one tablet twice\n  a day\" to a single interpretation.","- Output ONLY the SOAP note markdown. No preamble, no postscript."]}'::jsonb,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE "id" = 'tmpl_system_default_soap';
